import {Component, HostBinding, OnInit} from '@angular/core';
import {Router} from '@angular/router';
import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../shared';
import {Plugins} from '@capacitor/core';
import 'ocr';
import {HttpClientService} from '../../shared/http-client.service';
import {ModalService} from 'ng-zorro-antd-mobile';
import {environment} from '../../../environments/environment';
import {isNotNullOrUndefined} from 'codelyzer/util/isNotNullOrUndefined';

const { Ocr } = Plugins;
@Component({
    selector: 'app-tube-find-box',
    templateUrl: 'tube-find-box.page.html',
    styleUrls: ['tube-find-box.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class TubeFindBoxPage implements OnInit {
    boxInfo = {
        boxBarcode: '',
        boxId: '',
        boxState: '',
        censusAddress: '',
        closeTime: '',
        closeUser: '',
        inceptTime: '',
        inceptUser: '',
        openTime: '',
        openUser: '',
        patientNum: 0,
        sendTime: '',
        sendUser: '',
        tubeNum: 0,
    };
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private platform: Platform,
        private deleteModal: ModalService
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
    }

    ionViewWillEnter() {
    }

    // 路由返回
    routeBack() {
       // this.router.navigate(['/BoxList']);
         this.router.navigate(['/tabs/tab1']);
    }
    search(barcode){
        this.ListBoxTube(barcode);
    }

    // 调用后台接口
    // 根据箱查询所有管
    ListBoxTube(barcode){
        this.boxInfo = {
            boxBarcode: '',
            boxId: '',
            boxState: '',
            censusAddress: '',
            closeTime: '',
            closeUser: '',
            inceptTime: '',
            inceptUser: '',
            openTime: '',
            openUser: '',
            patientNum: 0,
            sendTime: '',
            sendUser: '',
            tubeNum: 0,
        };
        if (!isNotNullOrUndefined(barcode) || barcode.trim() === ''){
            this.http.showToast('管码为空，请输入管码');
            return;
        }
        const condition = {
            boxBarcode: barcode
        };
        this.http
            .get(`rcp/api/box/operate/getBoxInfoByTubeBarcode`, condition , '根据管查箱信息', '根据管查箱信息失败', {load: true})
            .subscribe( data => {
                if (data['isSuccess']){
                    this.boxInfo = data['data'];
               }
            });
    }
}
